/**
 * GetRentos design tokens — the single source of truth for colour, spacing,
 * radius, typography and elevation across web (Tailwind) and native (RN).
 *
 * Web CSS is generated by `pnpm tokens:sync`. Run `pnpm tokens:check` to verify
 * that browser and native palettes still agree.
 */

export type ColorScheme = 'light' | 'dark';

export interface Palette {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  border: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  primary: string;
  primaryHover: string;
  primaryForeground: string;
  destructive: string;
  destructiveForeground: string;
  info: string;
  success: string;
  warning: string;
  purple: string;
  infoSubtle: string;
  successSubtle: string;
  warningSubtle: string;
  purpleSubtle: string;
  destructiveSubtle: string;
  ring: string;
  /** Opaque overlay for modals / sheets. */
  scrim: string;
}

export const lightColors: Palette = {
  // Keep the page and working surfaces close enough to feel like one product,
  // while retaining a real elevation cue for grouped content.
  background: '#f7f7f8',
  foreground: '#1d1d1f',
  card: '#ffffff',
  cardForeground: '#1d1d1f',
  border: '#e5e5e9',
  secondary: '#f1f1f3',
  secondaryForeground: '#1d1d1f',
  muted: '#f3f3f5',
  mutedForeground: '#626268',
  accent: '#eaf3ff',
  accentForeground: '#0055b3',
  primary: '#0066cc',
  primaryHover: '#0055b3',
  primaryForeground: '#ffffff',
  destructive: '#c81e1e',
  destructiveForeground: '#ffffff',
  info: '#0066cc',
  success: '#0b7a3e',
  warning: '#99500a',
  purple: '#6840c2',
  infoSubtle: '#eaf3ff',
  successSubtle: '#e7f7ef',
  warningSubtle: '#fdf1e3',
  purpleSubtle: '#f3eefb',
  destructiveSubtle: '#fdecec',
  ring: 'rgba(0, 102, 204, 0.65)',
  scrim: 'rgba(29, 29, 31, 0.4)',
};

export const darkColors: Palette = {
  // A true dark canvas gives raised cards and controls a clear visual level.
  background: '#000000',
  foreground: '#f5f5f7',
  card: '#1c1c1e',
  cardForeground: '#f5f5f7',
  border: '#343437',
  secondary: '#2c2c2e',
  secondaryForeground: '#f5f5f7',
  muted: '#222225',
  mutedForeground: '#a1a1aa',
  accent: '#142b47',
  accentForeground: '#a6caff',
  primary: '#8db9ff',
  primaryHover: '#a6caff',
  primaryForeground: '#111113',
  destructive: '#f05656',
  destructiveForeground: '#111113',
  info: '#8db9ff',
  success: '#38c57a',
  warning: '#ffb454',
  purple: '#a78bfa',
  infoSubtle: '#142b47',
  successSubtle: '#0e2b1c',
  warningSubtle: '#2e1f0a',
  purpleSubtle: '#251a3f',
  destructiveSubtle: '#3a1517',
  ring: 'rgba(141, 185, 255, 0.75)',
  scrim: 'rgba(0, 0, 0, 0.6)',
};

export const colors: Record<ColorScheme, Palette> = {
  light: lightColors,
  dark: darkColors,
};

export const getPalette = (scheme: ColorScheme): Palette => colors[scheme];

/** 4-pt spacing scale. Use the semantic names, not raw numbers, in screens. */
export const spacing = {
  none: 0,
  xxs: 2,
  xs: 4,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 20,
  '2xl': 24,
  '3xl': 32,
  '4xl': 40,
  '5xl': 56,
  '6xl': 72,
} as const;

export type SpacingKey = keyof typeof spacing;

export const radius = {
  none: 0,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 20,
  '2xl': 28,
  full: 9999,
} as const;

export type RadiusKey = keyof typeof radius;

/**
 * Type ramp. `-apple-system` on the web resolves to San Francisco; on native
 * we let the platform pick its own UI face (SF on iOS, Roboto on Android) by
 * leaving `fontFamily` undefined and only setting weight.
 */
export const typography = {
  display: { fontSize: 34, lineHeight: 41, fontWeight: '700', letterSpacing: -0.5 },
  title: { fontSize: 28, lineHeight: 34, fontWeight: '600', letterSpacing: -0.4 },
  heading: { fontSize: 20, lineHeight: 26, fontWeight: '600', letterSpacing: -0.2 },
  subheading: { fontSize: 17, lineHeight: 24, fontWeight: '600', letterSpacing: -0.1 },
  body: { fontSize: 17, lineHeight: 24, fontWeight: '400', letterSpacing: -0.1 },
  bodyStrong: { fontSize: 17, lineHeight: 24, fontWeight: '600', letterSpacing: -0.1 },
  callout: { fontSize: 15, lineHeight: 22, fontWeight: '500', letterSpacing: 0 },
  caption: { fontSize: 13, lineHeight: 18, fontWeight: '400', letterSpacing: 0 },
  label: { fontSize: 12, lineHeight: 16, fontWeight: '600', letterSpacing: 0.1 },
} as const;

export type TypographyVariant = keyof typeof typography;

/**
 * Elevation. Shaped for React Native's `style` object; the web keeps its own
 * multi-layer box-shadows. `elevation` drives Android, `shadow*` drives iOS.
 */
export const shadows = {
  none: {},
  xs: {
    shadowColor: '#161b22',
    shadowOpacity: 0.05,
    shadowRadius: 2,
    shadowOffset: { width: 0, height: 1 },
    elevation: 1,
  },
  sm: {
    shadowColor: '#161b22',
    shadowOpacity: 0.08,
    shadowRadius: 8,
    shadowOffset: { width: 0, height: 3 },
    elevation: 3,
  },
  md: {
    shadowColor: '#161b22',
    shadowOpacity: 0.12,
    shadowRadius: 20,
    shadowOffset: { width: 0, height: 8 },
    elevation: 8,
  },
  lg: {
    shadowColor: '#161b22',
    shadowOpacity: 0.16,
    shadowRadius: 32,
    shadowOffset: { width: 0, height: 14 },
    elevation: 14,
  },
} as const;

export type ShadowKey = keyof typeof shadows;

export const duration = { fast: 120, base: 200, slow: 320 } as const;

export const tokens = { colors, spacing, radius, typography, shadows, duration };
export default tokens;
